import{mountPianoRoll}from'./music-piano-roll.js';
// A whole-song note overview, linked to a zoomed piano roll. Endpoints remain
// absolute ticks while navigating pages; selection is never reset by scrolling.
export function mountMotifRange({root,score,part,range,onRange,error=()=>{},editable=false,onChange}){
 let page=Math.floor(range.start/192),bars=2,tool='range',snap=6;const tr=score.tracks[part];
 root.innerHTML='<p class="hint-line">Drag across the overview or the notes to mark A–B. Drag the gold A/B lines to adjust an endpoint. Scroll mode pans without selecting.</p><div class="motif-overview"></div><div class="studio-actions"><button type="button" data-range-prev>← Earlier</button><button type="button" data-range-next>Later →</button><label>Visible bars<select data-range-zoom><option>1</option><option selected>2</option><option>4</option><option>8</option></select></label><label>Snap<select data-range-snap><option value="1">One tick</option><option value="3">1/32 note</option><option value="6" selected>1/16 note</option><option value="8">Triplet</option><option value="12">1/8 note</option><option value="24">Beat</option></select></label><label>Tool<select data-range-tool><option value="range">Select A–B</option><option value="scroll">Scroll</option>'+(editable?'<option value="select">Move / resize</option><option value="draw">Draw</option><option value="erase">Erase</option>':'')+'</select></label></div><output class="motif-range-label" aria-live="polite"></output><div class="music-roll touch-roll"></div>';
 const $=s=>root.querySelector(s),report=()=>{$('.motif-range-label').textContent=`A: bar ${(1+range.start/96).toFixed(2)} → B: bar ${(1+range.end/96).toFixed(2)} · ${tr.notes.filter(n=>n.tick<range.end&&n.tick+n.duration>range.start).length} notes selected`;},update=r=>{range.start=r.start;range.end=r.end;report();onRange?.({...range});};
 function overview(){const width=1000,height=120,notes=tr.notes,low=Math.min(48,...notes.map(n=>n.key)),high=Math.max(72,...notes.map(n=>n.key)),x=t=>t/score.length*width,y=k=>95-(k-low)/(high-low)*65,wrap=$('.motif-overview');wrap.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 120" role="application" aria-label="Whole song motif selection"><rect width="1000" height="120" fill="#263c37"/>${(score.songSections||[]).map(s=>`<text x="${x(s.start)+4}" y="14" fill="#e7eddb" font-size="12">${s.kind}</text>`).join('')}${notes.filter((_,i)=>i%Math.max(1,Math.ceil(notes.length/12000))===0).map(n=>`<rect x="${x(n.tick)}" y="${y(n.key)}" width="${Math.max(1,n.duration/score.length*width)}" height="3" fill="#b6d67f"/>`).join('')}<rect data-overview-range x="${x(range.start)}" y="18" width="${x(range.end-range.start)}" height="90" fill="#e3b654" opacity=".35"/><path data-overview-a d="M${x(range.start)} 18V110" stroke="#fff2b2" stroke-width="3"/><path data-overview-b d="M${x(range.end)} 18V110" stroke="#fff2b2" stroke-width="3"/></svg>`;const svg=wrap.querySelector('svg');let drag=null;const pos=e=>{const r=svg.getBoundingClientRect();return Math.max(0,Math.min(score.length,Math.round((e.clientX-r.left)/(r.width||1000)*score.length/snap)*snap));},paint=()=>{const a=svg.querySelector('[data-overview-range]');a.setAttribute('x',x(range.start));a.setAttribute('width',x(range.end-range.start));svg.querySelector('[data-overview-a]').setAttribute('d',`M${x(range.start)} 18V110`);svg.querySelector('[data-overview-b]').setAttribute('d',`M${x(range.end)} 18V110`);};svg.onpointerdown=e=>{if(e.isPrimary===false)return;e.preventDefault();svg.setPointerCapture?.(e.pointerId);drag={id:e.pointerId,tick:Math.min(score.length-snap,pos(e))};};svg.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const tick=pos(e);update({start:Math.min(drag.tick,tick),end:Math.min(score.length,Math.max(drag.tick,tick)+snap)});paint();};svg.onpointerup=e=>{if(!drag)return;const tick=pos(e);update({start:Math.min(drag.tick,tick),end:Math.min(score.length,Math.max(drag.tick,tick)+snap)});drag=null;page=Math.floor(range.start/(bars*96));roll();paint();};svg.onpointercancel=()=>drag=null;}
 function roll(){const b=mountPianoRoll({root:$('.touch-roll'),score,part,page,barsPerPage:bars,tool,quantum:snap,range,onRange:r=>{update(r);overview();},onChange:notes=>{tr.notes=notes;onChange?.(notes);draw();},error});page=b.page;$('[data-range-prev]').disabled=page===0;$('[data-range-next]').disabled=b.end>=score.length;report();}
 function draw(){overview();roll();}for(const [s,d]of [['[data-range-prev]',-1],['[data-range-next]',1]])$(s).onclick=()=>{page+=d;roll();};$('[data-range-zoom]').onchange=()=>{const at=page*bars*96;bars=+$('[data-range-zoom]').value;page=Math.floor(at/(bars*96));roll();};$('[data-range-snap]').onchange=()=>{snap=+$('[data-range-snap]').value;roll();};$('[data-range-tool]').onchange=()=>{tool=$('[data-range-tool]').value;roll();};draw();return{refresh(r){if(r)update(r);page=Math.floor(range.start/(bars*96));draw();}};
}
